# hypothesis: A TypedDict with NotRequired and Literal fields accepts a dict literal that omits the optional key, rejects a ReadOnly key assignment, and rejects a wrong Literal value statically while CPython accepts it.
from typing import Literal, NotRequired, ReadOnly, TypedDict, reveal_type


class User(TypedDict):
    name: str
    role: Literal['admin', 'guest']
    email: NotRequired[str]


class Config(TypedDict):
    mode: ReadOnly[Literal['dev', 'prod']]


def greet(u: User) -> str:
    if 'email' in u:
        reveal_type(u['email'])
        return u['name'] + ' <' + u['email'] + '>'
    return u['name']


def set_mode(c: Config) -> str:
    return c['mode']


def flip(c: Config) -> None:
    c['mode'] = 'prod'  # expect-error: ReadOnly key


def make_bad() -> User:
    return {'name': 'eve', 'role': 'root'}  # expect-error: 'root' is not in Literal


a: User = {'name': 'ann', 'role': 'admin'}
b: User = {'name': 'bob', 'role': 'guest', 'email': 'b@x'}
cfg: Config = {'mode': 'dev'}
assert greet(a) == 'ann'
assert greet(b) == 'bob <b@x>'
assert set_mode(cfg) == 'dev'
flip(cfg)
assert cfg['mode'] == 'prod'
assert make_bad()['role'] == 'root'
